changeSet.sql:
alter table case_page_settings add constraint ck_case_page_settings_wait
    check (wait_amber_minutes between 1 and 10080 and wait_red_minutes between 2 and 10080
           and wait_red_minutes > wait_amber_minutes);
alter table case_page_settings add constraint ck_case_page_settings_expiry
    check (empty_case_expiry_days between 1 and 365);
